                  "data": [
                    { "id": "chat-one", "game_id": "509658", "viewer_count": 12000 },
                    { "id": "chat-two", "game_id": "509658", "viewer_count": 300 },
                    { "id": "rust-one", "game_id": "263490", "viewer_count": 20 }
