                new ReplayChatMessage(
                    TimeSpan.FromMinutes(10),
                    new ChatMessage(PlatformKind.Twitch, "streamer", "viewer-b", "stable replay chat B", timestamp, MessageId: "stable-b"))
            ],
            TimeSpan.Zero,
            TimeSpan.FromHours(1)));
