        Assert.Equal(0, collectionChanges);
        Assert.SequenceEqual(
            new[] { "stable replay chat A", "stable replay chat B" },
            tab.DockedChatMessages.Select(message => message.Message).ToArray());

        await tab.DisposeAsync();
    }),
