    ("native replay overlay animation pacing yields when rendering is expensive", () =>
    {
        var cheapDelay = StreamTabViewModel.NormalizeNativeReplayOverlayAnimationDelay(
            TimeSpan.FromMilliseconds(20),
            TimeSpan.FromMilliseconds(5));
        var expensiveDelay = StreamTabViewModel.NormalizeNativeReplayOverlayAnimationDelay(
            TimeSpan.FromMilliseconds(20),
            TimeSpan.FromMilliseconds(80));
        var cappedDelay = StreamTabViewModel.NormalizeNativeReplayOverlayAnimationDelay(
            TimeSpan.FromMilliseconds(20),
            TimeSpan.FromSeconds(2));

        Assert.Equal(TimeSpan.FromMilliseconds(100), cheapDelay);
        Assert.Equal(TimeSpan.FromMilliseconds(240), expensiveDelay);
        Assert.Equal(TimeSpan.FromSeconds(1), cappedDelay);
        return Task.CompletedTask;
