        Assert.Equal(new DateTimeOffset(2026, 6, 1, 20, 5, 0, TimeSpan.Zero), vod.PublishedAtUtc);
        Assert.Equal(new TimeSpan(3, 8, 33), vod.Duration);
        Assert.Equal(12345, vod.ViewCount);
