        Assert.Equal("Just Chatting", offline.CategoryName);
        Assert.Equal(false, offline.CanPlay);
        Assert.Equal(false, streamlink.ProbeRequests.Any(request => request.Target.Platform == PlatformKind.Kick));
    }),
