                Assert.Equal(first, detachedWindow!.ActiveTab);
                Assert.SequenceEqual(new[] { first }, detachedWindow.Tabs);
            }
            finally
            {
                detachedWindow?.CloseForTabDisposal();
                window.Close();
            }

            return Task.CompletedTask;
        });
    }),
